test("AC-9: equal deadlines are ordered by reported_at, then job_id", () => {
  const bike = rentableBike();
  const base = Date.now() - 5 * HOUR;
  const iso = (ms: number) => new Date(ms).toISOString();
  // Same deadline three ways: a wrench at T, an inspection at T - 48h (96h limit), and a second
  // wrench at T with a later job_id.
  const rows = [
    ["J-AC9-C", "wrench", iso(base)],
    ["J-AC9-A", "inspection", iso(base - 48 * HOUR)],
    ["J-AC9-B", "wrench", iso(base)],
  ];
  const insert = database.query(
    "INSERT INTO repair_jobs VALUES (?, ?, ?, 'North', ?, 'LOCK', ?, ?, NULL)",
  );
  for (const [id, source, reported] of rows) {
    insert.run(id, bike.bike_id, bike.station_id, source, reported, reported);
  }
  try {
    const ids = crewQueue(database, null)
      .jobs.filter((job) => job.job_id.startsWith("J-AC9-"))
      .map((job) => job.job_id);
    expect(ids).toEqual(["J-AC9-A", "J-AC9-B", "J-AC9-C"]);
  } finally {
    database.query("DELETE FROM repair_jobs WHERE job_id LIKE 'J-AC9-%'").run();
  }
});
