// AC-5. The map shows the same counts as the feed.
import { expect, test } from "bun:test";
import { database, mapPage, recordWrench, rentableBike, stationStatus } from "./setup";

// The red badge after a station's dot carries its disabled count; no badge means 0.
function brokenOnMap(html: string, stationId: string): number {
  const after = html.split(`<title>${stationId} `)[1];
  if (!after) throw new Error(`station ${stationId} missing from map`);
  const nextDot = after.indexOf("<circle", after.indexOf("</circle>") + 1);
  const segment = nextDot === -1 ? after : after.slice(0, nextDot + 60);
  const badge = segment.match(/fill="#dc2626"\/><text [^>]*>(\d+)<\/text>/);
  return badge ? Number(badge[1]) : 0;
}

