// Shared setup for the acceptance tests. Bun runs every test file in one process and caches
// modules, so the temp paths are set once, before src/database is first imported (AGENTS.md).
import { tmpdir } from "node:os";
import { join } from "node:path";

const stamp = `${Date.now()}-${process.pid}`;
process.env.SPOKE_DB ??= join(tmpdir(), `spoke-acceptance-${stamp}.db`);
process.env.SPOKE_LOG ??= join(tmpdir(), `spoke-acceptance-${stamp}.log`);

const { openDatabase } = await import("../../src/database");
export const { stationStatus, vehicleStatus } = await import("../../src/feed");
export const { recordWrench } = await import("../../src/wrenches");
export const { crewQueue } = await import("../../src/crew-queue");
export const { mapPage } = await import("../../src/map-page");
export const { readCsv } = await import("../../src/csv");

export const database = openDatabase();
export const HOUR = 60 * 60 * 1000;

type Bike = { bike_id: string; station_id: string; is_disabled: number };

// A bike riders can rent right now. Tests disable the bikes they wrench, so each call returns
// a bike no earlier test has touched.
export function rentableBike(): Bike {
  return database
    .query("SELECT * FROM bikes WHERE is_disabled = 0 ORDER BY bike_id LIMIT 1")
    .get() as Bike;
}

export function disabledFlag(bikeId: string): number {
  const row = database.query("SELECT is_disabled FROM bikes WHERE bike_id = ?").get(bikeId);
  return (row as { is_disabled: number }).is_disabled;
}

export function stationEntry(stationId: string) {
  const entry = stationStatus(database).data.stations.find((s) => s.station_id === stationId);
  if (!entry) throw new Error(`station ${stationId} missing from station_status`);
  return entry;
}

export function vehicleEntry(bikeId: string) {
  const entry = vehicleStatus(database).data.vehicles.find((v) => v.vehicle_id === bikeId);
  if (!entry) throw new Error(`bike ${bikeId} missing from vehicle_status`);
  return entry;
}

export function countRows(table: "wrenches" | "repair_jobs", bikeId?: string): number {
  const row = bikeId
    ? database.query(`SELECT COUNT(*) AS n FROM ${table} WHERE bike_id = ?`).get(bikeId)
    : database.query(`SELECT COUNT(*) AS n FROM ${table}`).get();
  return (row as { n: number }).n;
}

// SLA-4: 48h from reported_at for a wrench, 96h for anything else.
export function expectedDeadline(job: { source: string; reported_at: string }): string {
  const limitHours = job.source === "wrench" ? 48 : 96;
  return new Date(Date.parse(job.reported_at) + limitHours * HOUR).toISOString();
}

type QueueJob = { job_id: string; reported_at: string; deadline: string };

// AC-9 order: deadline ascending, then reported_at, then job_id.
export function isContractOrder(jobs: QueueJob[]): boolean {
  const key = (job: QueueJob) => [job.deadline, job.reported_at, job.job_id];
  return jobs.every((job, i) => {
    if (i === 0) return true;
    const [a, b] = [key(jobs[i - 1]), key(job)];
    for (let k = 0; k < a.length; k++) {
      if (a[k] < b[k]) return true;
      if (a[k] > b[k]) return false;
    }
    return true;
  });
}

