// AC-5. The map shows the same counts as the feed.
import { expect, test } from "bun:test";
import { database, mapPage, recordWrench, rentableBike, stationStatus } from "./setup";

// The map draws each station as <circle ...><title>S-xxx Name</title></circle>, followed by a
// red badge with the disabled count when it is above 0.
function brokenOnMap(html: string, stationId: string): number {
  const start = html.indexOf(`<title>${stationId} `);
  if (start === -1) throw new Error(`station ${stationId} missing from map`);
  const rest = html.slice(html.indexOf("</circle>", start) + "</circle>".length);
  const badge = rest.match(/^<circle [^>]*fill="#dc2626"\/><text [^>]*>(\d+)<\/text>/);
  return badge ? Number(badge[1]) : 0;
}

test("AC-5: after a wrench the map matches station_status for that station and in total", () => {
  const bike = rentableBike();
  expect(recordWrench(database, { bike_id: bike.bike_id }).status).toBe(201);

  const html = mapPage(database);
  const stations = stationStatus(database).data.stations;
  const entry = stations.find((s) => s.station_id === bike.station_id);
  expect(entry?.num_vehicles_disabled).toBeGreaterThan(0);
  expect(brokenOnMap(html, bike.station_id)).toBe(entry?.num_vehicles_disabled ?? -1);

  const totalAvailable = stations.reduce((sum, s) => sum + s.num_vehicles_available, 0);
  const totalDisabled = stations.reduce((sum, s) => sum + s.num_vehicles_disabled, 0);
  expect(html).toContain(`<b>${totalAvailable}</b> bikes riders can rent`);
  expect(html).toContain(`<b class="red">${totalDisabled}</b> broken`);
});

