// AC-8. Deadlines count from the rider's report (SLA-4), never from opened_at.
import { expect, test } from "bun:test";
import { HOUR, crewQueue, database, expectedDeadline, recordWrench, rentableBike } from "./setup";

test("AC-8: every open job's deadline is reported_at + 48h (wrench) or + 96h (other)", () => {
  expect(recordWrench(database, { bike_id: rentableBike().bike_id }).status).toBe(201);
  const jobs = crewQueue(database, null).jobs;
  expect(jobs.some((job) => job.source === "wrench")).toBe(true);
  expect(jobs.some((job) => job.source !== "wrench")).toBe(true);
  for (const job of jobs) expect(job.deadline).toBe(expectedDeadline(job));
});

test("AC-8: opened_at is ignored when it is later than reported_at", () => {
  const bike = rentableBike();
  const reportedAt = new Date(Date.now() - 10 * HOUR).toISOString();
  const openedAt = new Date(Date.now() - 2 * HOUR).toISOString();
  database
    .query("INSERT INTO repair_jobs VALUES ('J-AC8', ?, ?, 'North', 'wrench', 'LOCK', ?, ?, NULL)")
    .run(bike.bike_id, bike.station_id, reportedAt, openedAt);
  try {
    const job = crewQueue(database, null).jobs.find((j) => j.job_id === "J-AC8");
    expect(job?.deadline).toBe(new Date(Date.parse(reportedAt) + 48 * HOUR).toISOString());
  } finally {
    database.query("DELETE FROM repair_jobs WHERE job_id = 'J-AC8'").run();
  }
});

