// AC-9. The job due first is on top; ties break on reported_at, then job_id.
import { expect, test } from "bun:test";
import { HOUR, crewQueue, database, isContractOrder, rentableBike } from "./setup";

test("AC-9: the queue, with and without depot, is sorted by deadline ascending", () => {
  for (const depot of [null, "North", "South"]) {
    const jobs = crewQueue(database, depot).jobs;
    expect(jobs.length).toBeGreaterThanOrEqual(2);
    expect(isContractOrder(jobs)).toBe(true);
    const earliest = jobs.map((job) => job.deadline).sort()[0];
    expect(jobs[0].deadline).toBe(earliest);
  }
});

test("AC-9: equal deadlines are ordered by reported_at, then job_id", () => {
  const bike = rentableBike();
  const base = Date.now() - 5 * HOUR;
  const iso = (ms: number) => new Date(ms).toISOString();
  // Three jobs with the same deadline: an inspection found at T - 48h (96h limit), and two
  // wrenches at T (48h limit) whose job_ids decide their order.
  const rows = [
    ["J-AC9-C", "wrench", iso(base)],
    ["J-AC9-A", "inspection", iso(base - 48 * HOUR)],
    ["J-AC9-B", "wrench", iso(base)],
  ];
  const insert = database.query(
    "INSERT INTO repair_jobs VALUES (?, ?, ?, 'North', ?, 'LOCK', ?, ?, NULL)",
  );
  for (const [id, source, reported] of rows) {
    insert.run(id, bike.bike_id, bike.station_id, source, reported, reported);
  }
  try {
    const ids = crewQueue(database, null)
      .jobs.filter((job) => job.job_id.startsWith("J-AC9-"))
      .map((job) => job.job_id);
    expect(ids).toEqual(["J-AC9-A", "J-AC9-B", "J-AC9-C"]);
  } finally {
    database.query("DELETE FROM repair_jobs WHERE job_id LIKE 'J-AC9-%'").run();
  }
});

