// AC-10. Jobs already open at launch (the 40 seed jobs) follow the contract.
import { expect, test } from "bun:test";
import { join } from "node:path";
import { HOUR, crewQueue, database, expectedDeadline, isContractOrder, readCsv } from "./setup";

const seed = readCsv(join(import.meta.dir, "..", "..", "data", "open-jobs.csv"));
const seedIds = new Set(seed.map((row) => row.job_id));
const seedJobs = () => crewQueue(database, null).jobs.filter((job) => seedIds.has(job.job_id));

test("AC-10: all 40 seed jobs use reported_at deadlines, moved earlier by 0.1h to 1.0h", () => {
  expect(seed).toHaveLength(40);
  const jobs = seedJobs();
  expect(jobs).toHaveLength(40);

  for (const job of jobs) {
    expect(job.deadline).toBe(expectedDeadline(job));
    const limitHours = job.source === "wrench" ? 48 : 96;
    const oldDeadline = Date.parse(job.opened_at) + limitHours * HOUR;
    const movedHours = (oldDeadline - Date.parse(job.deadline)) / HOUR;
    expect(movedHours).toBeGreaterThanOrEqual(0.1 - 1e-6);
    expect(movedHours).toBeLessThanOrEqual(1.0 + 1e-6);
  }
  expect(isContractOrder(crewQueue(database, null).jobs)).toBe(true);
});

test("AC-10: 0 seed jobs are overdue at launch", () => {
  const now = Date.now();
  expect(seedJobs().filter((job) => Date.parse(job.deadline) <= now)).toHaveLength(0);
});

