// AC-2. The wrench, the repair job and the disabled flag are recorded together.
import { expect, test } from "bun:test";
import { countRows, database, disabledFlag, recordWrench, rentableBike } from "./setup";

test("AC-2: a 201 wrench adds 1 wrench row, 1 open wrench job and disables the bike", () => {
  const bike = rentableBike();
  const wrenchesBefore = countRows("wrenches", bike.bike_id);
  const jobsBefore = countRows("repair_jobs", bike.bike_id);

  const outcome = recordWrench(database, { bike_id: bike.bike_id, fault: "CHAIN" });

  expect(outcome.status).toBe(201);
  expect(countRows("wrenches", bike.bike_id)).toBe(wrenchesBefore + 1);
  expect(countRows("repair_jobs", bike.bike_id)).toBe(jobsBefore + 1);
  const job = database
    .query("SELECT source, closed_at FROM repair_jobs WHERE job_id = ?")
    .get((outcome.body as { job_id: string }).job_id);
  expect(job).toEqual({ source: "wrench", closed_at: null });
  expect(disabledFlag(bike.bike_id)).toBe(1);
});

test("AC-2: if disabling the bike fails, neither the wrench nor the job is kept", () => {
  const bike = rentableBike();
  const wrenchesBefore = countRows("wrenches");
  const jobsBefore = countRows("repair_jobs");
  database.exec(`CREATE TEMP TRIGGER ac2_fail BEFORE UPDATE ON bikes
    WHEN NEW.bike_id = '${bike.bike_id}' BEGIN SELECT RAISE(ABORT, 'ac2 forced failure'); END;`);
  try {
    expect(() => recordWrench(database, { bike_id: bike.bike_id, fault: "LOCK" })).toThrow();
  } finally {
    database.exec("DROP TRIGGER ac2_fail");
  }
  expect(countRows("wrenches")).toBe(wrenchesBefore);
  expect(countRows("repair_jobs")).toBe(jobsBefore);
  expect(disabledFlag(bike.bike_id)).toBe(0);
});
EOF
